using Microsoft.EntityFrameworkCore;
using SchoolManagement.Domain.Academic;
using SchoolManagement.Domain.Admissions;
using SchoolManagement.Domain.Assessment;
using SchoolManagement.Domain.Attendance;
using SchoolManagement.Domain.Clinical;
using SchoolManagement.Domain.Examinations;
using SchoolManagement.Domain.Finance;
using SchoolManagement.Domain.Identity;
using SchoolManagement.Domain.Staff;
using SchoolManagement.Domain.Students;
using AssessmentGradingScale = SchoolManagement.Domain.Assessment.GradingScale;
using AssessmentGradeBand = SchoolManagement.Domain.Assessment.GradeBand;
using AssessmentTranscriptEntry = SchoolManagement.Domain.Assessment.TranscriptEntry;

namespace SchoolManagement.Infrastructure.Persistence;

public sealed class SchoolManagementDbContext(DbContextOptions<SchoolManagementDbContext> options) : DbContext(options)
{
 public DbSet<User> Users=>Set<User>(); public DbSet<Role> Roles=>Set<Role>(); public DbSet<UserRole> UserRoles=>Set<UserRole>(); public DbSet<Applicant> Applicants=>Set<Applicant>(); public DbSet<Student> Students=>Set<Student>(); public DbSet<StudentGuardian> StudentGuardians=>Set<StudentGuardian>(); public DbSet<Faculty> Faculties=>Set<Faculty>(); public DbSet<Department> Departments=>Set<Department>(); public DbSet<Programme> Programmes=>Set<Programme>(); public DbSet<AcademicYear> AcademicYears=>Set<AcademicYear>(); public DbSet<Semester> Semesters=>Set<Semester>(); public DbSet<Intake> Intakes=>Set<Intake>(); public DbSet<Course> Courses=>Set<Course>(); public DbSet<Curriculum> Curricula=>Set<Curriculum>(); public DbSet<CurriculumCourse> CurriculumCourses=>Set<CurriculumCourse>(); public DbSet<Admission> Admissions=>Set<Admission>(); public DbSet<StudentEnrollment> StudentEnrollments=>Set<StudentEnrollment>(); public DbSet<CourseRegistration> CourseRegistrations=>Set<CourseRegistration>(); public DbSet<CourseOffering> CourseOfferings=>Set<CourseOffering>(); public DbSet<TeachingGroup> TeachingGroups=>Set<TeachingGroup>(); public DbSet<TimetableEntry> TimetableEntries=>Set<TimetableEntry>(); public DbSet<AttendanceSession> AttendanceSessions=>Set<AttendanceSession>(); public DbSet<StudentAttendance> StudentAttendances=>Set<StudentAttendance>(); public DbSet<StudentAcademicStatus> StudentAcademicStatuses=>Set<StudentAcademicStatus>(); public DbSet<LearningOutcome> LearningOutcomes=>Set<LearningOutcome>(); public DbSet<AssessmentPlan> AssessmentPlans=>Set<AssessmentPlan>(); public DbSet<StudentAssessment> StudentAssessments=>Set<StudentAssessment>(); public DbSet<AssessmentResult> AssessmentResults=>Set<AssessmentResult>(); public DbSet<AssessmentGradingScale> GradingScales=>Set<AssessmentGradingScale>(); public DbSet<AssessmentGradeBand> GradeBands=>Set<AssessmentGradeBand>(); public DbSet<AssessmentTranscriptEntry> TranscriptEntries=>Set<AssessmentTranscriptEntry>(); public DbSet<ProgrammeAssessmentProfile> ProgrammeAssessmentProfiles=>Set<ProgrammeAssessmentProfile>(); public DbSet<AttendanceRecord> AttendanceRecords=>Set<AttendanceRecord>(); public DbSet<Placement> Placements=>Set<Placement>(); public DbSet<StudentPlacement> StudentPlacements=>Set<StudentPlacement>(); public DbSet<Result> Results=>Set<Result>(); public DbSet<ResultApproval> ResultApprovals=>Set<ResultApproval>(); public DbSet<FeeStructure> FeeStructures=>Set<FeeStructure>(); public DbSet<StudentInvoice> StudentInvoices=>Set<StudentInvoice>(); public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<StaffMember> StaffMembers=>Set<StaffMember>(); public DbSet<TeachingAllocation> TeachingAllocations=>Set<TeachingAllocation>();
 protected override void OnModelCreating(ModelBuilder m){
  m.Entity<UserRole>(e=>e.HasKey(x=>new{x.UserId,x.RoleId}));
  m.Entity<ProgrammeAssessmentProfile>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>x.ProgrammeId).IsUnique();e.Property(x=>x.Authority).HasConversion<string>().HasMaxLength(30).IsRequired();e.Property(x=>x.Family).HasConversion<string>().HasMaxLength(50).IsRequired();e.Property(x=>x.Model).HasConversion<string>().HasMaxLength(30).IsRequired();e.HasOne<Programme>().WithMany().HasForeignKey(x=>x.ProgrammeId).OnDelete(DeleteBehavior.Cascade);});
  m.Entity<AssessmentPlan>(e=>{e.HasKey(x=>x.Id);e.Property(x=>x.Name).HasMaxLength(150).IsRequired();e.Property(x=>x.AssessmentType).HasMaxLength(50).IsRequired();e.HasIndex(x=>new{x.CourseId,x.Name}).IsUnique();});
  m.Entity<StudentAssessment>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.CourseRegistrationId,x.AssessmentPlanId}).IsUnique();e.Property(x=>x.Grade).HasMaxLength(10);e.Property(x=>x.CompetencyLevel).HasMaxLength(50);e.HasOne<CourseRegistration>().WithMany().HasForeignKey(x=>x.CourseRegistrationId).OnDelete(DeleteBehavior.Restrict);e.HasOne<AssessmentPlan>().WithMany().HasForeignKey(x=>x.AssessmentPlanId).OnDelete(DeleteBehavior.Restrict);e.HasOne<Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);});
  m.Entity<AssessmentResult>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>x.CourseRegistrationId).IsUnique();e.Property(x=>x.Grade).HasMaxLength(10);e.HasOne<CourseRegistration>().WithMany().HasForeignKey(x=>x.CourseRegistrationId).OnDelete(DeleteBehavior.Restrict);e.HasOne<Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);});
  m.Entity<AssessmentGradingScale>(e=>{e.HasKey(x=>x.Id);e.Property(x=>x.Name).HasMaxLength(100).IsRequired();e.Property(x=>x.Description).HasMaxLength(500);e.HasIndex(x=>x.Name).IsUnique();});
  m.Entity<AssessmentGradeBand>(e=>{e.HasKey(x=>x.Id);e.Property(x=>x.Grade).HasMaxLength(10).IsRequired();e.HasIndex(x=>new{x.GradingScaleId,x.Grade}).IsUnique();e.HasOne<AssessmentGradingScale>().WithMany().HasForeignKey(x=>x.GradingScaleId).OnDelete(DeleteBehavior.Cascade);});
  m.Entity<AssessmentTranscriptEntry>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>x.CourseRegistrationId).IsUnique();e.Property(x=>x.CourseCode).HasMaxLength(30).IsRequired();e.Property(x=>x.CourseTitle).HasMaxLength(200).IsRequired();e.Property(x=>x.Grade).HasMaxLength(10);e.HasOne<Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);e.HasOne<CourseRegistration>().WithMany().HasForeignKey(x=>x.CourseRegistrationId).OnDelete(DeleteBehavior.Restrict);e.HasOne<AcademicYear>().WithMany().HasForeignKey(x=>x.AcademicYearId).OnDelete(DeleteBehavior.Restrict);e.HasOne<Semester>().WithMany().HasForeignKey(x=>x.SemesterId).OnDelete(DeleteBehavior.Restrict);});
  m.Entity<AcademicResultSummary>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.StudentId,x.AcademicYearId,x.SemesterId}).IsUnique();e.Property(x=>x.Standing).HasMaxLength(50).IsRequired();e.HasOne<Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);e.HasOne<AcademicYear>().WithMany().HasForeignKey(x=>x.AcademicYearId).OnDelete(DeleteBehavior.Restrict);e.HasOne<Semester>().WithMany().HasForeignKey(x=>x.SemesterId).OnDelete(DeleteBehavior.Restrict);});
  m.Entity<ResultApproval>(e=>{e.HasKey(x=>x.Id);e.HasIndex(x=>x.ResultId).IsUnique();e.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20).IsRequired();e.Property(x=>x.RejectionReason).HasMaxLength(1000);e.HasOne<Result>().WithMany().HasForeignKey(x=>x.ResultId).OnDelete(DeleteBehavior.Cascade);});
 }
}